/**
 * The data gateway (architecture rule AD-2).
 *
 * This is the only module that imports the JSON files. Everything else takes
 * data from the exports below. The files are copied into src/generated by
 * scripts/sync-data.mjs from data/processed, or from data/fixtures until the
 * pipeline has produced real data.
 *
 * One file is not part of the data contract: src/content/briefs.json, the SI briefs of the
 * preset environments. They are written from the ranking and the gaps, which the site computes,
 * so they live with the site (docs/decisions.md).
 */

import briefsJson from "@/content/briefs.json";
import type { Brief, BriefFile } from "@/domain/types";
import type { DataBundle, Investigation, Meta, Scenario, TestRecord } from "@/generated/contract";
import investigationsJson from "@/generated/investigations.json";
import metaJson from "@/generated/meta.json";
import scenariosJson from "@/generated/scenarios.json";
import sourceJson from "@/generated/source.json";
import testsJson from "@/generated/tests.json";

export type DataSource = "fixtures" | "processed";

export const tests = testsJson as unknown as TestRecord[];
export const investigations = investigationsJson as unknown as Investigation[];
export const scenarios = scenariosJson as unknown as Scenario[];
export const meta = metaJson as unknown as Meta;

/** "fixtures" means the site is showing hand-made sample rows, not the full PSI data. */
export const dataSource = sourceJson.source as DataSource;

export const data: DataBundle = { tests, investigations, scenarios, meta };

const investigationsById = new Map(investigations.map((item) => [item.id, item]));

export function getInvestigation(id: string): Investigation | undefined {
  return investigationsById.get(id as Investigation["id"]);
}

const testsById = new Map(tests.map((row) => [row.id, row]));

export function getTest(id: string): TestRecord | undefined {
  return testsById.get(id);
}

export function getTestsOfInvestigation(id: string): TestRecord[] {
  return tests.filter((row) => row.investigationId === id);
}

export function getScenario(id: string): Scenario | undefined {
  return scenarios.find((item) => item.id === id);
}

/** The SI briefs and who wrote them. A brief is shown only after verifyBrief has passed it. */
export const briefFile = briefsJson as BriefFile;

export function getBrief(scenarioId: string): Brief | undefined {
  return briefFile.briefs.find((item) => item.scenarioId === scenarioId);
}
